/*
We have a 3x3x3 cube of standard dice.
Opposite faces sum to 7.

Coordinates:
x = 0..2 left -> right
y = 0..2 front -> back
z = 0..2 bottom -> top

Visible views:
- Top view gives number on +z face for each (x,y)
- Front view gives number on -y face for each (x,z)

Need all possible assignments/orientations of 27 dice consistent with both views.
For each valid arrangement compute sum of numbers on right side (+x faces) of the 9 dice with x=2.
Output distinct sums ascending, or 0 if none.

Key observation:
Each die is independent except for matching its visible top/front values if visible.
No constraints between different dice.

For one die:
Given possibly top value T and/or front value F, determine all possible right-face values R
among all die orientations satisfying those visible values.
Then overall possible sums are combinations over the 9 right-side dice (x=2), while
all other dice only need existence of at least one orientation.

Standard die orientation constraints:
- Opposite faces sum to 7.
- For an oriented die, if top=T and front=F, then T != F and T+F != 7.
  Then right can be one of two values, depending on chirality:
  among the four numbers excluding T and 7-T and F and 7-F, exactly two remain? Actually
  with fixed top and front adjacent, right is determined up to sign/orientation around axis:
  it can be one of the two numbers adjacent to both, which are opposite to each other.
We can generate all 24 orientations once and query exactly.
*/

typedef struct {
    int U, D, L, R, F, B; /* Up, Down, Left, Right, Front, Back */
} Ori;

Ori oris[24];
int ori_cnt = 0;

int same_ori(Ori a, Ori b) {
    return a.U==b.U && a.D==b.D && a.L==b.L && a.R==b.R && a.F==b.F && a.B==b.B;
}

void add_ori(Ori o) {
    for (int i = 0; i < ori_cnt; i++) {
        if (same_ori(oris[i], o)) return;
    }
    oris[ori_cnt++] = o;
}

Ori roll_x(Ori o) { /* rotate forward: front->up */
    Ori r = o;
    r.U = o.F;
    r.F = o.D;
    r.D = o.B;
    r.B = o.U;
    r.L = o.L;
    r.R = o.R;
    return r;
}

Ori roll_y(Ori o) { /* rotate right around front-back axis: left->up */
    Ori r = o;
    r.U = o.L;
    r.R = o.U;
    r.D = o.R;
    r.L = o.D;
    r.F = o.F;
    r.B = o.B;
    return r;
}

Ori roll_z(Ori o) { /* rotate clockwise around vertical axis: front->right */
    Ori r = o;
    r.F = o.L;
    r.R = o.F;
    r.B = o.R;
    r.L = o.B;
    r.U = o.U;
    r.D = o.D;
    return r;
}

void gen_oris() {
    Ori start = {1,6,4,3,2,5}; /* any valid standard die */
    Ori queue[100];
    int qh = 0, qt = 0;
    queue[qt++] = start;
    add_ori(start);
    while (qh < qt) {
        Ori cur = queue[qh++];
        Ori nxt[3] = { roll_x(cur), roll_y(cur), roll_z(cur) };
        for (int i = 0; i < 3; i++) {
            int old = ori_cnt;
            add_ori(nxt[i]);
            if (ori_cnt > old) queue[qt++] = nxt[i];
        }
    }
}

