import java.io.*;
import java.util.*;

/*
We have a 3x3x3 cube of standard dice.
Opposite faces sum to 7.

Input:
Repeated datasets.
Each dataset consists of 6 lines:
- 3 lines: top view (3 chars each)
- 3 lines: front view (3 chars each)
Each char is either '1'..'6' or '*' (unknown).
A line "0" ends input.

Goal:
Find all possible arrangements of the 27 dice consistent with the views.
For every valid full arrangement, compute the sum of visible numbers on the right side
(3x3 = 9 dice). Output all distinct sums in ascending order, space-separated.
If no arrangement exists, output 0.

Interpretation used:
- Top view gives the upward face of the top-layer dice: positions (x,y,2), printed by rows y=0..2 and cols x=0..2.
- Front view gives the front face of the front-layer dice: positions (x,0,z), printed by rows z=2..0? We must choose a convention.
  We use rows from top to bottom corresponding to z=2,1,0, which is the natural "front view".
- Right side sum uses the right face of dice at x=2 for all y,z.

Dice orientation:
A die orientation is determined by which number is on U,D,N,S,W,E.
Standard constraint only: opposite faces sum to 7.
All 24 cube rotations are allowed.

Approach:
Precompute all 24 orientations of a standard die.
For each cell, allowed orientations are filtered by top/front constraints if applicable.
Then do DP layer-by-layer with row/column compatibility:
Adjacent dice touching each other must have equal numbers on the touching faces.
Specifically:
- along x: E(left die) == W(right die)
- along y: S(front?) / N(back?) equality; with our coordinates y increasing backward, adjacent (x,y,z) and (x,y+1,z): S of back-neighbor? Simpler:
  we define N = face toward decreasing y (front), S = face toward increasing y (back).
  Then touching requires S of (x,y,z) == N of (x,y+1,z).
- along z: U(lower) == D(upper) for touching internal faces.

We enumerate plane states for each z layer (3x3 orientations) satisfying x/y compat and top constraints (for z=2) and front constraints (for y=0 cells in all z).
Then stack 3 layers with z-compatibility.

Finally collect right-side sums from x=2 cells.
*/

public class Main {
    static class Ori {
        int U, D, N, S, W, E;
        Ori(int U, int D, int N, int S, int W, int E) {
            this.U = U; this.D = D; this.N = N; this.S = S; this.W = W; this.E = E;
        }
    }

    static List<Ori> orientations = new ArrayList<>();

    static void genOrientations() {
        // BFS over rotations from one canonical die:
        // U=1, D=6, N=2, S=5, W=3, E=4 is arbitrary but valid with opposites summing to 7.
        Ori start = new Ori(1,6,2,5,3,4);
        Set<String> seen = new HashSet<>();
        ArrayDeque<Ori> q = new ArrayDeque<>();
        q.add(start);
        while (!q.isEmpty()) {
            Ori o = q.poll();
            String key = o.U+","+o.D+","+o.N+","+o.S+","+o.W+","+o.E;
            if (!seen.add(key)) continue;
            orientations.add(o);
            // rotate around x-axis: U<-S, D<-N, N<-U, S<-D
            q.add(new Ori(o.S, o.N, o.U, o.D, o.W, o.E));
            // rotate around y-axis: U<-W, D<-E, W<-D, E<-U
            q.add(new Ori(o.W, o.E, o.N, o.S, o.D, o.U));
            // rotate around z-axis: N<-E, S<-W, W<-N, E<-S
            q.add(new Ori(o.U, o.D, o.E, o.W, o.N, o.S));
        }
    }

    static class LayerState {
        int[] idx; // 9 orientation indices
        int[] up;  // U values
        int[] down;// D values
        int rightSum;
        LayerState(int[] idx) {
            this.idx = idx.clone();
            up = new int[9];
            down = new int[9];
            rightSum = 0;
            for (int i = 0; i < 9; i++) {
                Ori o = orientations.get(idx[i]);
                up[i] = o.U;
                down[i] = o.D;
                int x = i % 3;
                if (x == 2) rightSum += o.E;
            }
        }
    }

    static char[][] top = new char[3][3];
    static char[][] front = new char[3][3];

    static ArrayList<Integer>[][][] allowed; // [x][y][z] list of orientation indices

    static void buildAllowed() {
        allowed = new ArrayList[3][3][3];
        for (int x = 0; x < 3; x++) for (int y = 0; y < 3; y++) for (int z = 0; z < 3; z++) {
            allowed[x][y][z] = new ArrayList<>();
            for (int i = 0; i < orientations.size(); i++) {
                Ori o = orientations.get(i);
                boolean ok = true;
                if (z == 2) {
                    char c = top[y][x];
                    if (c != '*' && o.U != c - '0') ok = false;
                }
                if (y == 0) {
                    char c = front[2 - z][x]; // front rows top->bottom correspond z=2..0
                    if (c != '*' && o.N != c - '0') ok = false;
                }
                if (ok) allowed[x][y][z].add(i);
            }
        }
    }

    static ArrayList<LayerState>[] layersByZ;

    static void genLayerStatesForZ(int z) {
        ArrayList<LayerState> res = new ArrayList<>();
        int[] cur = new int[9];
        dfsLayer(z, 0, cur, res);
        layersByZ[z] = res;
    }

    static void dfsLayer(int z, int pos, int[] cur, ArrayList<LayerState> res) {
        if (pos == 9) {
            res.add(new LayerState(cur));
            return;
        }
        int x = pos % 3;
        int y = pos / 3;
        for (int idx : allowed[x][y][z]) {
            Ori o = orientations.get(idx);
            if (x > 0) {
                Ori left = orientations.get(cur[pos - 1]);
                if (left.E != o.W) continue;
            }
            if (y > 0) {
                Ori frontNeighbor = orientations.get(cur[pos - 3]); // (x,y-1,z)
                if (frontNeighbor.S != o.N) continue;
            }
            cur[pos] = idx;
            dfsLayer(z, pos + 1, cur, res);
        }
    }

    static boolean compatible(LayerState low, LayerState high) {
        for (int i = 0; i < 9; i++) {
            if (low.up[i] != high.down[i]) return false;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        genOrientations();

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder out = new StringBuilder();

        while (true) {
            line = br.readLine();
            if (line == null) break;
            if (line.equals("0")) break;
            top[0] = line.toCharArray();
            for (int i = 1; i < 3; i++) top[i] = br.readLine().toCharArray();
            for (int i = 0; i < 3; i++) front[i] = br.readLine().toCharArray();

            buildAllowed();

            boolean impossible = false;
            for (int x = 0; x < 3; x++) for (int y = 0; y < 3; y++) for (int z = 0; z < 3; z++) {
                if (allowed[x][y][z].isEmpty()) impossible = true;
            }

            if (impossible) {
                out.append("0\n");
                continue;
            }

            layersByZ = new ArrayList[3];
            for (int z = 0; z < 3; z++) genLayerStatesForZ(z);

            if (layersByZ[0].isEmpty() || layersByZ[1].isEmpty() || layersByZ[2].isEmpty()) {
                out.append("0\n");
                continue;
            }

            TreeSet<Integer> sums = new TreeSet<>();

            ArrayList<LayerState> L0 = layersByZ[0];
            ArrayList<LayerState> L1 = layersByZ[1];
            ArrayList<LayerState> L2 = layersByZ[2];

            // Precompute compatibility lists for speed.
            List<Integer>[] next01 = new ArrayList[L0.size()];
            for (int i = 0; i < L0.size(); i++) {
                next01[i] = new ArrayList<>();
                for (int j = 0; j < L1.size(); j++) {
                    if (compatible(L0.get(i), L1.get(j))) next01[i].add(j);
                }
            }
            List<Integer>[] next12 = new ArrayList[L1.size()];
            for (int i = 0; i < L1.size(); i++) {
                next12[i] = new ArrayList<>();
                for (int j = 0; j < L2.size(); j++) {
                    if (compatible(L1.get(i), L2.get(j))) next12[i].add(j);
                }
            }

            for (int i = 0; i < L0.size(); i++) {
                LayerState a = L0.get(i);
                for (int j : next01[i]) {
                    LayerState b = L1.get(j);
                    for (int k : next12[j]) {
                        LayerState c = L2.get(k);
                        sums.add(a.rightSum + b.rightSum + c.rightSum);
                    }
                }
            }

            if (sums.isEmpty()) {
                out.append("0\n");
            } else {
                boolean first = true;
                for (int v : sums) {
                    if (!first) out.append(' ');
                    first = false;
