# ------------------------------------------------------------
# 27 dice cube reconstruction from top/front views.
#
# We have a 3x3x3 cube of standard dice.
# Opposite faces sum to 7.
#
# Input:
# Repeated datasets, each consisting of 18 integers:
#   9 integers for the top view  (3x3)
#   9 integers for the front view (3x3)
# Datasets continue until EOF.
#
# For each dataset:
#   Determine all possible cube arrangements consistent with the
#   given top and front visible numbers.
#   For each valid arrangement, compute the sum of the numbers on
#   the right side of the whole 3x3x3 cube (9 visible dice).
#   Output all distinct such sums in ascending order, or 0 if none.
#
# ------------------------------------------------------------

# All 24 cube orientations represented as (U, D, F, B, L, R)
def generate_orientations():
    # start with one valid labeling
    start = (1, 6, 2, 5, 3, 4)

    def roll_n(o):  # front -> up
        U, D, F, B, L, R = o
        return (F, B, D, U, L, R)

    def roll_s(o):  # back -> up
        U, D, F, B, L, R = o
        return (B, F, U, D, L, R)

    def roll_e(o):  # left -> up
        U, D, F, B, L, R = o
        return (L, R, F, B, D, U)

    def roll_w(o):  # right -> up
        U, D, F, B, L, R = o
        return (R, L, F, B, U, D)

    def spin(o):  # rotate around vertical axis
        U, D, F, B, L, R = o
        return (U, D, L, R, B, F)

    seen = set()
    res = []
    stack = [start]
    while stack:
        o = stack.pop()
        if o in seen:
            continue
        seen.add(o)
        res.append(o)
        stack.extend([roll_n(o), roll_s(o), roll_e(o), roll_w(o), spin(o)])
    return res

ORIENTS = generate_orientations()

# For each (top, front), possible right values among valid die orientations
possible_right = [[[] for _ in range(7)] for __ in range(7)]
for o in ORIENTS:
    U, D, F, B, L, R = o
    possible_right[U][F].append(R)

# Standard die validity for adjacent faces
def valid_top_front(t, f):
    if t == f:
        return False
    if t + f == 7:
        return False
    return True

