def solve_dataset(topv, frontv):
    # Coordinates:
    # x = 0..2 left->right
    # y = 0..2 front->back
    # z = 0..2 bottom->top
    #
    # top view gives topv[y][x] = top of highest visible die at (x,y), i.e. z=2
    # front view gives frontv[z_from_top][x]
    # front visible die for each (x,z) is y=0
    #
    # So:
    #   top number at all (x,y,2) is fixed
    #   front number at all (x,0,z) is fixed

    # domains[x][y][z] = list of possible right-face values for dice satisfying
    # the imposed top/front constraints at that position
    domains = [[[None] * 3 for _ in range(3)] for __ in range(3)]

    for x in range(3):
        for y in range(3):
            for z in range(3):
                top_req = topv[y][x] if z == 2 else None
                front_req = frontv[2 - z][x] if y == 0 else None

                vals = []
                if top_req is not None and front_req is not None:
                    if valid_top_front(top_req, front_req):
                        vals = possible_right[top_req][front_req][:]
                elif top_req is not None:
                    # any front adjacent to top_req
                    rr = []
                    for f in range(1, 7):
                        if valid_top_front(top_req, f):
                            rr.extend(possible_right[top_req][f])
                    vals = rr
                elif front_req is not None:
                    rr = []
                    for t in range(1, 7):
                        if valid_top_front(t, front_req):
                            rr.extend(possible_right[t][front_req])
                    vals = rr
                else:
                    vals = [o[5] for o in ORIENTS]

                vals = sorted(set(vals))
                if not vals:
                    return []
                domains[x][y][z] = vals

    # For neighboring dice:
    # along x, right faces must be opposite:
    # if die A right = r, then die B right = 7-r
    # along y, front faces opposite. Since front may vary, use orientation consistency.
    # along z, top faces opposite.
    #
    # To keep state small, represent each die by the full set of feasible orientations
    # under local constraints, then propagate equality/opposite constraints.

    orient_domains = [[[None] * 3 for _ in range(3)] for __ in range(3)]
    for x in range(3):
        for y in range(3):
            for z in range(3):
                top_req = topv[y][x] if z == 2 else None
                front_req = frontv[2 - z][x] if y == 0 else None
                cand = []
                for o in ORIENTS:
                    U, D, F, B, L, R = o
                    if top_req is not None and U != top_req:
                        continue
                    if front_req is not None and F != front_req:
                        continue
                    cand.append(o)
                if not cand:
                    return []
                orient_domains[x][y][z] = cand

    # Precompute compatibility
    # x-neighbor: right of left die == left of right die => R_left + R_right = 7
    # y-neighbor: back of front die == front of back die => B_front == F_back => F_front + F_back = 7
    # z-neighbor: top of lower die == bottom of upper die => U_lower + U_upper = 7
    def comp_x(a, b):
        return a[5] + b[5] == 7

    def comp_y(a, b):
        return a[2] + b[2] == 7

    def comp_z(a, b):
        return a[0] + b[0] == 7

    cells = [(x, y, z) for x in range(3) for y in range(3) for z in range(3)]

    neighbors = {}
    for x, y, z in cells:
        nb = []
        if x + 1 < 3:
            nb.append(((x + 1, y, z), 'x+'))
        if x - 1 >= 0:
            nb.append(((x - 1, y, z), 'x-'))
        if y + 1 < 3:
            nb.append(((x, y + 1, z), 'y+'))
        if y - 1 >= 0:
            nb.append(((x, y - 1, z), 'y-'))
        if z + 1 < 3:
            nb.append(((x, y, z + 1), 'z+'))
        if z - 1 >= 0:
            nb.append(((x, y, z - 1), 'z-'))
        neighbors[(x, y, z)] = nb

    def compatible(o1, o2, rel):
        if rel == 'x+':
            return comp_x(o1, o2)
        if rel == 'x-':
            return comp_x(o2, o1)
        if rel == 'y+':
            return comp_y(o1, o2)
        if rel == 'y-':
            return comp_y(o2, o1)
        if rel == 'z+':
            return comp_z(o1, o2)
        if rel == 'z-':
            return comp_z(o2, o1)
        return False

    # AC-3 style pruning
    def propagate(dom):
        changed = True
        while changed:
            changed = False
            for c in cells:
                cur = dom[c[0]][c[1]][c[2]]
                newcur = []
                for o in cur:
                    ok = True
                    for nc, rel in neighbors[c]:
                        nd = dom[nc[0]][nc[1]][nc[2]]
                        if not any(compatible(o, oo, rel) for oo in nd):
                            ok = False
                            break
                    if ok:
                        newcur.append(o)
                if not newcur:
                    return False
                if len(newcur) != len(cur):
                    dom[c[0]][c[1]][c[2]] = newcur
                    changed = True
        return True

    dom = [[[orient_domains[x][y][z][:] for z in range(3)] for y in range(3)] for x in range(3)]
    if not propagate(dom):
        return []

    sums = set()

    # backtracking
    def dfs():
        # choose cell with minimum remaining values > 1
        best = None
        best_len = 10
        complete = True
        for x, y, z in cells:
            l = len(dom[x][y][z])
            if l > 1:
                complete = False
                if l < best_len:
                    best_len = l
                    best = (x, y, z)
        if complete:
            s = 0
            # right side is x=2, sum right faces
            for y in range(3):
                for z in range(3):
                    s += dom[2][y][z][0][5]
            sums.add(s)
            return

        x, y, z = best
        options = dom[x][y][z][:]
        for o in options:
            saved = [[[dom[i][j][k][:] for k in range(3)] for j in range(3)] for i in range(3)]
            dom[x][y][z] = [o]
            if propagate(dom):
                dfs()
            dom[:] = saved

    dfs()
    return sorted(sums)

