    // We'll generate all rotations by rotating around axes.
    // We'll store as arrays of 6 values: [top, front, right, bottom, back, left]
    vector<array<int,6>> base = {{1,2,3,6,5,4}};
    // apply rotations:
    // rotate around vertical axis (top-bottom): changes front,right,back,left
    auto rot_y = [](array<int,6> d) -> array<int,6> {
        // new top=old top, new bottom=old bottom
        // front -> left, left -> back, back -> right, right -> front
        return {d[0], d[4], d[1], d[3], d[2], d[5]}; //? Let's define: index: 0 top,1 front,2 right,3 bottom,4 back,5 left
