        // new right = old front.
        // new back = old right.
        // new left = old back.
        // So mapping: {0,5,0,3,1,4}? Let's just do explicit.
        array<int,6> res;
        res[0] = d[0]; // top
        res[3] = d[3]; // bottom
        res[1] = d[5]; // front = left
        res[2] = d[1]; // right = front
        res[4] = d[2]; // back = right
        res[5] = d[4]; // left = back
        return res;
    };
    // rotate around front-back axis: changes top,right,bottom,left
    auto rot_x = [](array<int,6> d) -> array<int,6> {
        // looking from front, clockwise: top->right->bottom->left->top
        // new top = old left? Actually: top becomes right? Let's derive:
        // front stays, back stays.
        // top -> right, right -> bottom, bottom -> left, left -> top.
        array<int,6> res;
        res[1] = d[1]; // front
        res[4] = d[4]; // back
        res[0] = d[5]; // top = left
        res[2] = d[0]; // right = top
        res[3] = d[2]; // bottom = right
        res[5] = d[3]; // left = bottom
        return res;
    };
    // rotate around left-right axis: changes top,front,bottom,back
    auto rot_z = [](array<int,6> d) -> array<int,6> {
        // looking from right, clockwise: top->back->bottom->front->top
        // left and right stay.
        array<int,6> res;
        res[2] = d[2]; // right
        res[5] = d[5]; // left
        res[0] = d[4]; // top = back
        res[4] = d[3]; // back = bottom
        res[3] = d[1]; // bottom = front
        res[1] = d[0]; // front = top
        return res;
