/*
We have a 3x3x3 cube of standard dice.
Opposite faces sum to 7.

Input:
Repeated datasets, each consisting of 6 lines:
- 3 lines: top view (3 chars each)
- 3 lines: front view (3 chars each)
A cell is either a digit '1'..'6' or '*' (unknown).
Input ends with a line "#".

For every valid arrangement of 27 dice consistent with the views,
compute the sum of the visible right-side numbers of the 9 dice on the right face.
Output all distinct possible sums in ascending order, space-separated.
If none, output 0.

Interpretation used:
For each column (x,y) in top view, the visible top number is the top face of the
highest die present in that vertical stack. Since the cube is full 3x3x3, that is
exactly the die at z=2.
For each cell (x,z) in front view, the visible front number is the front face of
the die at y=0.

Thus constraints are on:
- top layer z=2: U[x][y]
- front layer y=0: F[x][z]

Each die orientation must satisfy standard die adjacency/opposites.
We only care about top/front/right values. For a die, once top and front are known
and adjacent, right is determined up to sign/orientation; in fact uniquely.

We enumerate all possible (top, front, right) triples of a standard die.
Then for every cube position independently:
- if constrained by top and/or front, allowed triples are filtered.
- otherwise any triple.

Right-face sum depends only on positions x=2.
Since dice are independent, the set of possible sums is just the Minkowski sum of
possible right-values for the 9 right-face positions, provided every position has
at least one valid orientation.

Need correct right values from standard die.
We construct all 24 orientations by rotating a labeled die.
Base labeling:
U=1, D=6, N(front)=2, S(back)=5, W=3, E=4
This satisfies opposites sum to 7.
*/

struct Ori {
    int U, D, N, S, W, E;
};

Ori rotX(const Ori& a) { // rotate forward: U->S, N->U, D->N, S->D
    return {a.S, a.N, a.U, a.D, a.W, a.E};
}
Ori rotY(const Ori& a) { // rotate right around vertical: N->W, E->N, S->E, W->S
    return {a.U, a.D, a.E, a.W, a.N, a.S};
}
Ori rotZ(const Ori& a) { // spin clockwise looking from top: U same, N->W? choose consistent
    return {a.U, a.D, a.W, a.E, a.S, a.N};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Generate all 24 orientations.
    vector<Ori> all;
    {
        Ori base{1,6,2,5,3,4};
        queue<Ori> q;
        set<array<int,6>> vis;
        auto key = [&](const Ori& o){
            return array<int,6>{o.U,o.D,o.N,o.S,o.W,o.E};
        };
        q.push(base);
        vis.insert(key(base));
        while(!q.empty()) {
            Ori cur = q.front(); q.pop();
            all.push_back(cur);
            vector<Ori> nxt = {rotX(cur), rotY(cur), rotZ(cur)};
            for (auto &t : nxt) {
                auto k = key(t);
                if (!vis.count(k)) {
                    vis.insert(k);
                    q.push(t);
                }
            }
        }
    }

    string line;
    while (true) {
        vector<string> top(3), front(3);
        if (!(cin >> line)) return 0;
        if (line == "#") break;
        top[0] = line;
        for (int i = 1; i < 3; ++i) cin >> top[i];
        for (int i = 0; i < 3; ++i) cin >> front[i];

        bool ok = true;

        // possible right values for each right-face cell (y,z) at x=2
        vector<vector<int>> rightVals(3, vector<int>(3, -1));
        vector<vector<vector<int>>> allowedR(3, vector<vector<int>>(3));

        // Check every position has at least one orientation.
        for (int x = 0; x < 3 && ok; ++x) {
            for (int y = 0; y < 3 && ok; ++y) {
                for (int z = 0; z < 3 && ok; ++z) {
                    char tc = (z == 2 ? top[y][x] : '*');     // top rows are y, cols x
                    char fc = (y == 0 ? front[2 - z][x] : '*'); // front rows top->bottom correspond z=2..0

                    vector<int> rs;
                    for (auto &o : all) {
                        if (tc != '*' && o.U != tc - '0') continue;
                        if (fc != '*' && o.N != fc - '0') continue;
                        rs.push_back(o.E); // right face
                    }
                    if (rs.empty()) {
                        ok = false;
                        break;
                    }
                    if (x == 2) {
                        sort(rs.begin(), rs.end());
                        rs.erase(unique(rs.begin(), rs.end()), rs.end());
                        allowedR[y][z] = rs;
                    }
                }
            }
        }

        if (!ok) {
            cout << 0 << '\n';
            continue;
        }

        // DP over 9 right-face positions for possible sums.
        set<int> sums;
        sums.insert(0);
        for (int y = 0; y < 3; ++y) {
            for (int z = 0; z < 3; ++z) {
                set<int> ns;
                for (int s : sums) {
                    for (int r : allowedR[y][z]) ns.insert(s + r);
                }
                sums.swap(ns);
            }
        }

        if (sums.empty()) {
            cout << 0 << '\n';
        } else {
            bool first = true;
            for (int s : sums) {
                if (!first) cout << ' ';
                first = false;
                cout << s;
            }
            cout << '\n';
        }
    }
    return 0;
}
